import numpy as np
from rdkit import Chem
from collections import Counter
cp=Chem.AddHs(Chem.MolFromSmiles('[C-]1(C)C(C)=C(C)C(C)=C1CC([O-])(C(F)(F)F)C(F)(F)F'))
lig=Chem.AddHs(Chem.MolFromSmiles('Cc1cccc(C)c1N/C(C)=N/Cc1ccccn1'))
x=np.load('final.npz')['coords'];xc=x[:34];xl=x[34:];rh=np.zeros(3)
def ang(a,b,c):
 u=a-b;v=c-b;return np.degrees(np.arccos(np.dot(u,v)/np.linalg.norm(u)/np.linalg.norm(v)))
print('Cp coords and tether:')
for i in [0,2,4,6,8,9,10,11]: print(i,xc[i])
print('tether bond angles:',[(inds,ang(*[xc[i] for i in inds])) for inds in [(8,9,10),(9,10,11)]])
print('Rh O C',ang(rh,xc[11],xc[10]))
print('N Rh N',ang(xl[11],rh,xl[18]));print('O Rh Ns',[ang(xc[11],rh,xl[i]) for i in [11,18]])
print('N donor angle',[(i,[(n,ang(rh,xl[i],xl[n])) for n in [b.GetIdx() for b in lig.GetAtomWithIdx(i).GetNeighbors()] if n<19]) for i in [11,18]])
# closest intramol distances separated by >2 bonds
for m,z in [(cp,xc),(lig,xl)]:
 graph=Chem.GetDistanceMatrix(m)
 pairs=[]
 for i in range(len(z)):
  for j in range(i):
   if graph[i,j]>2:
    d=np.linalg.norm(z[i]-z[j]);ss=m.GetAtomWithIdx(i).GetSymbol()+m.GetAtomWithIdx(j).GetSymbol()
    if d<1.6: pairs.append((i,j,ss,d))
 print('clashes',pairs)
print(Counter([a.GetSymbol() for a in cp.GetAtoms()]+[a.GetSymbol() for a in lig.GetAtoms()]+['Rh']))
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
fig=plt.figure(figsize=(12,9));ax=fig.add_subplot(projection='3d')
colors={'C':'#555555','H':'#cccccc','F':'#80c455','N':'#3050f8','O':'#ed3030','Rh':'#aa33aa'}
for m,z in [(cp,xc),(lig,xl)]:
 for b in m.GetBonds():
