ax.scatter(0,0,0,s=180,color=colors['Rh']);ax.text(0,0,0,'Rh')
for z in [xc[11],xl[11],xl[18]]:ax.plot(*np.array([rh,z]).T,color='purple',lw=2)
ax.plot([0,0],[0,0],[0,1.85],color='purple',lw=2)
